import { mkdir, readFile, writeFile, unlink } from 'node:fs/promises';
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { platform, release } from 'node:os';
import sharp from 'sharp';
import { addOrientationFixtures } from './orientation-fixtures.mjs';

// Generated bytes stay in ignored output; never use a visitor's photos as test fixtures.
const root = new URL('../../output/image-codecs/fixtures/', import.meta.url);
await mkdir(root, { recursive: true });
const files = [];
async function save(name, data, details) {
  await writeFile(new URL(name, root), data);
  files.push({ name, source: 'synthetic: generated colored quadrants; no camera or personal input',
    ...details, bytes: data.length, sha256: createHash('sha256').update(data).digest('hex'),
    signature: data.subarray(0, 16).toString('hex') });
}
const width = 96, height = 64;
const rgba = Buffer.alloc(width * height * 4);
for (let y = 0; y < height; y++) for (let x = 0; x < width; x++) {
  const offset = (y * width + x) * 4;
  rgba.set([x < width / 2 ? 240 : 24, y < height / 2 ? 30 : 220, (x * 17 + y * 13) % 256, 255], offset);
}
const image = () => sharp(rgba, { raw: { width, height, channels: 4 } });
await save('quadrants.jpg', await image().jpeg().toBuffer(), { tags: ['jpeg'], width, height, expected: 'static' });
await save('quadrants.webp', await image().webp({ lossless: true }).toBuffer(), { tags: ['webp'], width, height, expected: 'static' });
await save('quadrants.png', await image().png().toBuffer(), { tags: ['png'], width, height, expected: 'static' });
const alpha = Buffer.from(rgba);
for (let pixel = 0; pixel < width * height; pixel++) alpha[pixel * 4 + 3] = [0, 64, 128, 255][pixel % 4];
await save('alpha.png', await sharp(alpha, { raw: { width, height, channels: 4 } }).png().toBuffer(), { tags: ['png', 'alpha'], width, height, expected: 'preserve RGBA including hidden RGB at alpha=0' });
await save('alpha.rgba', alpha, { tags: ['pixel-reference'], expected: 'exact decoded alpha.png pixels' });
const metadata = {
  IFD0: { Make: 'ZERO_SYNTHETIC_DEVICE', Model: 'CODEC_TEST_ONLY' },
  IFD3: { GPSLatitudeRef: 'N', GPSLatitude: '1/1 2/1 3/1', GPSLongitudeRef: 'E', GPSLongitude: '4/1 5/1 6/1' },
};
for (const orientation of [1, 3, 6, 8]) {
  await save(`orientation-${orientation}.jpg`, await image().withMetadata({ orientation }).withExifMerge(metadata).jpeg().toBuffer(),
    { tags: ['jpeg', 'orientation', 'gps', 'device'], width, height, orientation, expected: `apply EXIF ${orientation} once; remove source metadata` });
}
const xmp = '<x:xmpmeta xmlns:x="adobe:ns:meta/"><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#"><rdf:Description xmlns:zero="urn:zero:synthetic" zero:Marker="ZERO_SYNTHETIC_XMP"/></rdf:RDF></x:xmpmeta>';
await save('metadata.png', await image().withExif(metadata).withXmp(xmp).png().toBuffer(), { tags: ['png', 'gps', 'device', 'xmp'], width, height, expected: 'remove eXIf and XMP; preserve RGBA' });
await save('damaged.jpg', Buffer.from([0xff, 0xd8, 0xff, 0xe1, 0, 50, 0]), { tags: ['damaged'], expected: 'invalid' });
await save('png-disguised.jpg', await image().png().toBuffer(), { tags: ['disguised'], width, height, expected: 'identify PNG from bytes, not JPEG extension' });
await save('animated.webp', await sharp(Buffer.concat([rgba, alpha]), { raw: { width, height: height * 2, channels: 4, pageHeight: height } }).webp({ loop: 0, delay: [100, 100] }).toBuffer(), { tags: ['webp', 'animation'], width, height, expected: 'unsupported animation' });
if (platform() !== 'darwin') throw new Error('HEIC fixture generation requires macOS Apple ImageIO (sips). Do not silently substitute JPEG.');
for (const [label, w, h] of [['12mp', 4032, 3024], ['48mp', 8064, 6048]]) {
  const input = new URL(`source-${label}.png`, root);
  const output = new URL(`synthetic-${label}.heic`, root);
  await image().resize(w, h, { fit: 'fill' }).png().toFile(fileURLToPath(input));
  execFileSync('/usr/bin/sips', ['-s', 'format', 'heic', fileURLToPath(input), '--out', fileURLToPath(output)], { stdio: 'pipe' });
  const dimensions = execFileSync('/usr/bin/sips', ['-g', 'pixelWidth', '-g', 'pixelHeight', fileURLToPath(output)], { encoding: 'utf8' });
  if (!dimensions.includes(`pixelWidth: ${w}`) || !dimensions.includes(`pixelHeight: ${h}`)) throw new Error(`Wrong primary dimensions: ${label}`);
  await save(`synthetic-${label}.heic`, await readFile(output), { source: `synthetic: Apple ImageIO sips HEIC encode on ${platform()} ${release()}; generated quadrants, original HEIC bytes, no picker`,
    tags: [`heic-${label}`], width: w, height: h, cameraOriginal: false, expected: 'decode primary at original dimensions, or explicitly reject by measured policy' });
  await unlink(input);
}
await writeFile(new URL('manifest.json', root), JSON.stringify({ personalData: false, generator: 'website/experiments/image-codecs/generate-fixtures.mjs', sharp: sharp.versions.sharp, files }, null, 2) + '\n');
await addOrientationFixtures(root);
console.log(`Generated ${files.length + 5} synthetic fixtures in ignored website/output/image-codecs/fixtures/`);
